using System.Threading;
using System.Threading.Tasks;

namespace Automaticks.Diagnostics.CodeAnalysis.Analyzers.Tests;

/// <summary>
///     Tests for GeneratedCodeMarkerAnalyzer.
/// </summary>
public class GeneratedCodeMarkerAnalyzerTests
{
    private const string MarkedSource = """
                                        // <auto-generated/>
                                        namespace MyApp {
                                            public class Foo {}
                                        }
                                        """;
    private const string PlainSource = """
                                       namespace MyApp {
                                           public class Foo {}
                                       }
                                       """;

    /// <summary>
    ///     Tests that Analyze_AutoGeneratedHeaderInSourceFile_ReportsDiagnostic.
    /// </summary>
    /// <param name="cancellationToken">The cancellation token.</param>
    /// <returns>A task representing the asynchronous test operation.</returns>
    [Test]
    public async Task Analyze_AutoGeneratedHeaderInSourceFile_ReportsDiagnostic(CancellationToken cancellationToken)
    {
        var options = new AnalysisOptions
        {
            FilePath = "C:\\repo\\src\\Foo.cs"
        };

        var analyzer = new GeneratedCodeMarkerAnalyzer();
        var diagnostics = await AnalyzerTestRunner.AnalyzeAsync(analyzer, MarkedSource, options, cancellationToken);

        await Assert.That(DiagnosticCollectionAssertions.HasId(diagnostics, "ATXDC021")).IsTrue();
    }

    /// <summary>
    ///     Tests that Analyze_AutoGeneratedHeaderUnderBin_ReportsNoDiagnostic.
    /// </summary>
    /// <param name="cancellationToken">The cancellation token.</param>
    /// <returns>A task representing the asynchronous test operation.</returns>
    [Test]
    public async Task Analyze_AutoGeneratedHeaderUnderBin_ReportsNoDiagnostic(CancellationToken cancellationToken)
    {
        var options = new AnalysisOptions
        {
            FilePath = "C:\\repo\\bin\\Debug\\Foo.cs"
        };

        var analyzer = new GeneratedCodeMarkerAnalyzer();
        var diagnostics = await AnalyzerTestRunner.AnalyzeAsync(analyzer, MarkedSource, options, cancellationToken);

        await Assert.That(DiagnosticCollectionAssertions.HasId(diagnostics, "ATXDC021")).IsFalse();
    }

    /// <summary>
    ///     Tests that Analyze_AutoGeneratedHeaderUnderObj_ReportsNoDiagnostic.
    /// </summary>
    /// <param name="cancellationToken">The cancellation token.</param>
